import React, { useState, useRef } from 'react';

import {
    View,
    Text,
    TouchableOpacity,
    Dimensions,
    TextInput,
    TextInputProps,
    ActivityIndicator
} from 'react-native';

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';

import api from '../../../services/api';

export function LoginMenu() {
    const [alertCancelPurchaseActive, setAlertCancelPurchaseActive] = useState(false)
    const [loadFinishing, setLoadFinishing] = useState(false);

    const {
        shoppingCartItem,
        loginMenuActive,
    } = useContexState();

    const {
        setLoginMenuActive,
        setShoppingCartItem,
        setShoppingCartActive,
    } = useContexState();


    const conta = (shoppingCartItem.length) * 19.90;
    const price = (conta).toLocaleString("pt-BR", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    });


    const inputName = useRef('');
    const inputSenha = useRef('');


    function InputName({ style }: TextInputProps) {
        const [syntaxError, setSyntaxerror] = useState(false);

        return (
            <TextInput
                style={[styles.input, style, syntaxError ? { color: '#E22222' } : null]}
                onChangeText={text => inputName.current = text}
                maxLength={40}
                autoCorrect={false}
                spellCheck={false}
            />

        );
    };


    function InputSenha({ style }: TextInputProps) {
        const [syntaxError, setSyntaxerror] = useState(false);

        return (
            <TextInput
                style={[styles.input, style, syntaxError ? { color: '#E22222' } : null]}
                onChangeText={text => inputSenha.current = text}
                maxLength={9}
                autoCorrect={false}
                spellCheck={false}
            />
        );
    };


    function Load() {
        return (
            <>
                <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center', marginHorizontal: 10 }}>Finalizando compra!</Text>
                <ActivityIndicator size={37} color='#fff' style={{ marginTop: 10, marginBottom: 20 }} />
            </>
        );
    }


    function ButtonBuy() {
        function UpdateData(i: number) {
            setLoadFinishing(true);
            api.put("updateBuy", {
                number: shoppingCartItem[i],
                name: inputName.current,
                phone: inputSenha.current,
            }).then((response) => {
                //console.log(response.data);
                setLoadFinishing(false);
            });
        };

        if (inputName.current !== '' && inputSenha.current !== '') {
            for (let i = 0; i < shoppingCartItem.length; i++) {
                UpdateData(i);
                console.log(`PayOk ${shoppingCartItem[i]}`);
            };
        };
    };



    function Menu() {
        return (
            <>
                <View style={{ width: 250 }} >
                    <Text style={{ color: '#fff', fontSize: 20 }}>Usuário</Text>
                    <InputName />
                </View>

                <View style={{ width: 250 }} >
                    <Text style={{ color: '#fff', fontSize: 20 }}>Senha</Text>
                    <InputSenha />
                </View>

                <TouchableOpacity onPress={() => { }} style={styles.buttonPay} >
                    <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center' }}>Entrar</Text>
                    <Text style={{ color: '#fff', fontSize: 16, textAlign: 'center' }}>Apenas para representantes</Text>
                </TouchableOpacity>
            </>
        );
    }


    return (
        !loginMenuActive ? <>
            <TouchableOpacity onPress={() => {
                setAlertCancelPurchaseActive(true);
            }} style={styles.containeMain} />

            <View style={styles.container} >
                {loadFinishing ? <Load /> : <Menu />}
            </View>
        </> : null
    );
};
